INSERT INTO permissions(code) VALUES ('SHOP_DELETE'),('REWARD_CREATE'),('REWARD_DELETE'),('PRO_PLAN_CREATE'),('PRO_PLAN_DELETE'),('PRO_CODE_UPDATE'),('COMMUNITY_CREATE'),('COMMUNITY_UPDATE'),('COMMUNITY_DELETE');
INSERT INTO role_permissions(role_id,permission_code)
SELECT r.id,p.code FROM roles r CROSS JOIN permissions p
WHERE r.name='ADMIN' AND p.code IN ('SHOP_DELETE','REWARD_CREATE','REWARD_DELETE','PRO_PLAN_CREATE','PRO_PLAN_DELETE','PRO_CODE_UPDATE','COMMUNITY_CREATE','COMMUNITY_UPDATE','COMMUNITY_DELETE');
